import { useState } from 'react';
import './styles.css';

export type Row = {
  id: string;
  label: string;
  score: number | null;
};

export type Props = { rows: Row[] };

export function Component({ rows }: Props) {
  const [direction, setDirection] = useState<'none' | 'ascending' | 'descending'>('none');
  const orderedRows = rows.map((row, index) => ({ row, index }));

  if (direction !== 'none') {
    orderedRows.sort((a, b) => {
      if (a.row.score === null && b.row.score === null) {
        return a.index - b.index;
      }
      if (a.row.score === null) return 1;
      if (b.row.score === null) return -1;

      const difference = a.row.score - b.row.score;
      if (difference === 0) return a.index - b.index;
      return direction === 'ascending' ? difference : -difference;
    });
  }

  return (
    <section className="score-table" data-testid="panel">
      <button
        type="button"
        onClick={() => setDirection((current) =>
          current === 'ascending' ? 'descending' : 'ascending'
        )}
      >
        Sort score
      </button>
      <table aria-label="Rows">
        <thead>
          <tr>
            <th scope="col">Label</th>
            <th scope="col" aria-sort={direction}>Score</th>
          </tr>
        </thead>
        <tbody>
          {orderedRows.map(({ row }) => (
            <tr key={row.id}>
              <td>{row.label}</td>
              <td>{row.score === null ? '—' : row.score}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length === 0 && <p role="status">No rows</p>}
    </section>
  );
}
