import { useState } from 'react';
import './styles.css';

export type Unit = 'C' | 'F';
export type Props = {
  initialValue: string;
  initialUnit: Unit;
};

export function Component({ initialValue, initialUnit }: Props) {
  const [value, setValue] = useState(initialValue);
  const [unit, setUnit] = useState(initialUnit);
  const trimmedValue = value.trim();
  const matchesDecimal = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(trimmedValue);
  const numericValue = Number(trimmedValue);
  const converted = unit === 'C'
    ? numericValue * 9 / 5 + 32
    : (numericValue - 32) * 5 / 9;
  const valid = matchesDecimal
    && Number.isFinite(numericValue)
    && Number.isFinite(converted);
  const targetUnit = unit === 'C' ? 'F' : 'C';

  return (
    <div className="unit-converter" data-testid="panel">
      <label>
        Temperature
        <input
          type="text"
          value={value}
          aria-invalid={!valid}
          onChange={(event) => setValue(event.currentTarget.value)}
        />
      </label>
      <label>
        From unit
        <select
          value={unit}
          onChange={(event) => setUnit(event.currentTarget.value === 'C' ? 'C' : 'F')}
        >
          <option value="C">C</option>
          <option value="F">F</option>
        </select>
      </label>
      <output aria-label="Converted">
        {valid ? converted.toFixed(2) + ' ' + targetUnit : 'Invalid temperature'}
      </output>
      <button
        type="button"
        disabled={!valid}
        onClick={() => {
          if (!valid) return;
          setValue(converted.toFixed(2));
          setUnit(targetUnit);
        }}
      >
        Swap
      </button>
    </div>
  );
}
