import { useState } from 'react';
import './styles.css';

export type Range = {
  start: number;
  end: number;
};

export type Props = {
  min: number;
  max: number;
  onApply: (range: Range) => void;
};

export function Component({ min, max, onApply }: Props) {
  const [start, setStart] = useState('');
  const [end, setEnd] = useState('');
  const [error, setError] = useState({
    message: '',
    startInvalid: false,
    endInvalid: false,
  });
  const options = Array.from(
    { length: max - min + 1 },
    (_, index) => min + index,
  );

  return (
    <form
      aria-label="Range pair"
      className="range-pair"
      data-testid="panel"
      onSubmit={(event) => {
        event.preventDefault();

        if (start === '' || end === '') {
          setError({
            message: 'Choose both values',
            startInvalid: start === '',
            endInvalid: end === '',
          });
          return;
        }

        const startValue = Number(start);
        const endValue = Number(end);
        if (startValue > endValue) {
          setError({
            message: 'Range order',
            startInvalid: false,
            endInvalid: true,
          });
          return;
        }

        setError({
          message: '',
          startInvalid: false,
          endInvalid: false,
        });
        onApply({ start: startValue, end: endValue });
      }}
    >
      <label>
        Start
        <select
          value={start}
          aria-invalid={error.startInvalid}
          onChange={(event) => setStart(event.currentTarget.value)}
        >
          <option value="">Choose</option>
          {options.map((option) => (
            <option key={option} value={String(option)}>{option}</option>
          ))}
        </select>
      </label>
      <label>
        End
        <select
          value={end}
          aria-invalid={error.endInvalid}
          onChange={(event) => setEnd(event.currentTarget.value)}
        >
          <option value="">Choose</option>
          {options.map((option) => (
            <option key={option} value={String(option)}>{option}</option>
          ))}
        </select>
      </label>
      {error.message && <p role="alert">{error.message}</p>}
      <button type="submit">Apply</button>
    </form>
  );
}
